<?php declare(strict_types=1); namespace App\Core\Middleware; use App\Core\Request; use App\Core\Response; use App\Core\UnauthorizedException; final class PlatformAuthMiddleware { public function handle(Request $request,\Closure $next):Response{if(!\App\Core\Session::has('platform_user_id'))throw new UnauthorizedException('Platform authentication required.');return $next($request);} }